onal)</span></label><input id="add-service-note" name="internal_note" value="{{ old('internal_note') }}" maxlength="2000" class="form-control @error('internal_note') is-invalid @enderror">@error('internal_note')<div class="invalid-feedback">{{ $message }}</div>@enderror</div><div class="col-12"><button class="btn btn-outline-primary">Add to Same Request</button></div></div></form>@endif
