@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{[...document.querySelectorAll('.card-header')].find(h=>h.textContent.trim()==='Selected Services')?.closest('.card')?.remove();document.querySelectorAll('select[name*="[scope_statuses]"]').forEach(select=>select.remove());if(document.getElementById('processing-checklist')&&!document.querySelector('#processing-checklist .badge.text-bg-secondary')){[...document.querySelectorAll('h2.h6')].find(h=>h.textContent.trim()==='Completion')?.closest('form')?.remove()}const select=document.getElementById('add-service-id');const requestFee=document.getElementById('add-service-request-fee');const sync=()=>{if(!select)return;const option=select.selectedOptions[0];document.getElementById('add-service-default-fee').value=option?.dataset.defaultFee?`₹${option.dataset.defaultFee}`:'';document.getElementById('add-service-gst-rate').value=option?.dataset.gstRate?`${option.dataset.gstRate}%`:'';document.getElementById('add-service-estimated-days').value=option?.dataset.estimatedDays||'After review';if(requestFee&&!requestFee.dataset.edited)requestFee.value=option?.dataset.defaultFee||''};requestFee?.addEventListener('input',()=>requestFee.dataset.edited='1');select?.addEventListener('change',()=>{if(requestFee)delete requestFee.dataset.edited;sync()});sync()});</script>@endpush
